import {TEMPLATES,ASPECTS,ORIGINALS,BLESSING_PRESETS,blessingOptions,hasBlessingHeading,setBlessing,matchingDesign,newBlessingPage,applyArtwork,setTextVisibility,uid,clone,block,newPage,defaultProject,dimensions,escapeHTML as esc,parseCSV,parseGuestList,hasGuestName,bulkGreetingPage,prepareBulkProject,familyInvitationPages,validateProject,safeFilename} from './data.js';
import {drawPage,drawTimeline,readyImages,loadImage,hitTest,totalDuration,assetMedia} from './render.js';
import {download,makeZip,exportImages,exportVideo,supportedVideoType} from './export.js';
import {TRACKS,createMusicSession} from './music.js';

const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let project=defaultProject(),pageIndex=0,selectedId=null,activeTab='details',libraryTab='templates',filter='all',search='',zoom=1,bounds=[],busy=false;
let history=[],future=[],saveTimer,toastTimer,drag=null,previewFrame=null,previewMusic=null,previewPlaying=false,previewSeconds=0,musicSample=null,sampleTimer,db=null;
const canvas=$('#card-canvas'),modal=$('#modal');
const page=()=>project.pages[pageIndex];
const selected=()=>page().blocks.find(b=>b.id===selectedId);
function snapshot(){return {...project,pages:clone(project.pages),music:{...project.music},assets:[...project.assets]};}
function checkpoint(){history.push(snapshot());if(history.length>25)history.shift();future=[];updateHistory();}
function updateHistory(){$('#undo').disabled=!history.length||busy;$('#redo').disabled=!future.length||busy;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function change(fn,{panel=true,record=true}={}){if(busy)return;if(record)checkpoint();stopPreview();fn();redraw({panel});saveDraft();}
function saveDraft(){clearTimeout(saveTimer);$('#save-status').textContent='Saving…';saveTimer=setTimeout(async()=>{try{if(!db){$('#save-status').textContent='Save project to keep a copy';return;}const tx=db.transaction('drafts','readwrite');tx.objectStore('drafts').put(project,'current');await new Promise((res,rej)=>{tx.oncomplete=res;tx.onerror=()=>rej(tx.error);tx.onabort=()=>rej(tx.error);});$('#save-status').textContent='Draft saved';}catch{$('#save-status').textContent='Download project to save';}},600);}
async function initDB(){if(!globalThis.indexedDB)return;try{db=await new Promise((res,rej)=>{const req=indexedDB.open('mehfil-studio',1);req.onupgradeneeded=()=>req.result.createObjectStore('drafts');req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error);});const draft=await new Promise((res,rej)=>{const req=db.transaction('drafts').objectStore('drafts').get('current');req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error);});if(draft){project=validateProject(draft);toast('Welcome back. Your invitation is right here.');}}catch{$('#save-status').textContent='Save project to keep a copy';}}
function field(label,value,attr,type='text'){return `<label class="form-field"><span>${label}</span><input type="${type}" ${attr} value="${esc(value)}"></label>`;}
function area(label,value,attr){return `<label class="form-field"><span>${label}</span><textarea dir="auto" ${attr} rows="2">${esc(value)}</textarea></label>`;}
function selectField(label,value,attr,options){return `<label class="form-field"><span>${label}</span><select aria-label="${esc(label)}" ${attr}>${options.map(([v,l])=>`<option value="${esc(v)}" ${value===v?'selected':''}>${l}</option>`).join('')}</select></label>`;}
function section(label){return `<div class="section-label">${label}</div>`;}
function draw(){if(previewPlaying)return;bounds=drawPage(canvas,project,page(),{width:800,time:1.2,selection:selectedId,showSelection:true});fitCanvas();}
function fitCanvas(){const box=$('#canvas-area'),{height}=dimensions(project.aspect,800);const availableWidth=Math.max(150,box.clientWidth-(window.innerWidth<450?70:48));const maxHeight=project.mode==='video'?410:452;const ratio=Math.min(availableWidth/800,maxHeight/height)*zoom;const wrap=$('#canvas-wrap');wrap.style.width=`${800*ratio}px`;wrap.style.height=`${height*ratio}px`;$('#zoom-value').textContent=zoom===1?'Fit':`${Math.round(zoom*100)}%`;}
function redraw({panel=true,templates=false}={}){
  const artwork=project.assets.find(a=>a.id===page().mediaId);const hasText=artwork&&artwork.kind!=='frame';$('#artwork-notice').hidden=!hasText;if(hasText)$('#artwork-notice').textContent='This artwork already contains lettering. Add only the extra words you need, or choose an editable template to change the invitation details.';$('#canvas-tip').textContent=hasText?'✧ Original lettering stays part of the image.':'✥ Click any text to make it yours. Drag to move.';$('#clear-text').disabled=!artwork;$('#remove-background').disabled=!artwork;
  $('#project-name').value=project.name;$('#aspect').value=project.aspect;$$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===project.mode));$('#preview-controls').hidden=project.mode!=='video';
  if(templates)renderTemplates();else $$('.template-card').forEach(b=>b.classList.toggle('active',b.dataset.template===page().template&&!page().mediaId));
  draw();renderPages();if(panel)renderInspector();updateHistory();updateTime();
}
function renderTemplates(){const grid=$('#template-grid');grid.innerHTML='';const filtered=TEMPLATES.filter(t=>(filter==='all'||t.category===filter)&&`${t.name} ${t.label}`.toLowerCase().includes(search));if(!filtered.length){grid.innerHTML='<p class="empty">No designs found. Try another style.</p>';return;}
  for(const t of filtered){const b=document.createElement('button');b.className=`template-card ${page().template===t.id&&!page().mediaId?'active':''}`;b.dataset.template=t.id;b.setAttribute('aria-label',`Use ${t.name} template`);b.innerHTML=`<span class="template-art"><canvas width="200" height="280" aria-hidden="true"></canvas></span><span class="selected-tick">✓</span><span class="template-name">${esc(t.name)}</span><span class="template-category">${esc(t.label)}</span>`;grid.append(b);const demo=newPage(t.id);drawPage(b.querySelector('canvas'),{...project,mode:'image',aspect:'portrait',assets:[]},demo,{width:220,time:2});}
}
function renderPages(){$('#page-count').textContent=String(project.pages.length).padStart(2,'0');const strip=$('#page-thumbnails');strip.innerHTML='';for(const [i,p] of project.pages.entries()){const b=document.createElement('button');b.className=`page-thumb ${i===pageIndex?'active':''}`;b.dataset.page=i;b.setAttribute('aria-label',`Edit page ${i+1}: ${p.name}`);b.innerHTML=`<canvas aria-hidden="true"></canvas><span>${String(i+1).padStart(2,'0')}<small>${esc(p.name.slice(0,15))}</small></span>`;strip.append(b);drawPage(b.querySelector('canvas'),{...project,mode:'image'},p,{width:100,time:2});}}

const labels={overline:'Celebration heading',name1:'First name',name2:'Second name',ampersand:'Between the names',host:'Hosted with love by',message:'Your invitation message',date:'Date',time:'Time',venue:'Venue',address:'City / address',footer:'A little finishing touch',schedule:'The schedule',recipient:'Personalized greeting',family1:'First person’s family / son of',family2:'Second person’s family / daughter of',eventTitle:'Ceremony / reception wording',rsvp:'RSVP names & contact',compliments:'With best compliments from'};
const OCCASIONS=[['wedding','Wedding','THE WEDDING CELEBRATION OF','celebrate their wedding'],['nikah','Nikah','THE NIKAH CEREMONY OF','celebrate their Nikah'],['walima','Walima','THE WALIMA RECEPTION OF','celebrate their Walima reception'],['engagement','Engagement','THE ENGAGEMENT CELEBRATION OF','celebrate their engagement'],['mehndi','Mehndi','A MEHNDI CELEBRATION FOR','celebrate an evening of mehndi'],['sangeet','Sangeet','AN EVENING OF MUSIC & LOVE','celebrate an evening of sangeet'],['reception','Reception','A RECEPTION TO CELEBRATE','celebrate their wedding reception'],['anniversary','Anniversary','ANOTHER CHAPTER OF LOVE','celebrate their anniversary'],['custom','Something of your own','','']];
const occasionTitle=id=>({wedding:'Wedding Ceremony',nikah:'Nikah Ceremony',walima:'Walima Reception',engagement:'Engagement Ceremony',mehndi:'Mehndi Celebration',sangeet:'Sangeet',reception:'Wedding Reception',anniversary:'Anniversary Celebration'})[id]||'Our celebration';
function relatedBlessing(){return page().kind==='blessing'||hasBlessingHeading(page())?page():project.pages[pageIndex-1]?.kind==='blessing'?project.pages[pageIndex-1]:null;}
function blessingControl(){const p=relatedBlessing();return `<div class="blessing-control"><div><strong>Opening words</strong><span>${p?`${esc(BLESSING_PRESETS.find(([id])=>id===blessingOptions(p).preset)?.[1]||'Your words')} · ${p.kind==='blessing'?'Opening page':'Above the invitation'}`:'An optional blessing, in your chosen design.'}</span></div><button class="button outline full" data-action="blessing">${p?'Edit blessing':'＋ Add a blessing'}</button>${p?'<button class="quiet full" data-action="remove-blessing">Remove blessing</button>':''}</div>`;}
function detailField(key,multiline=false){const b=page().blocks.find(b=>b.key===key&&!b.hidden);if(!b)return '';return (multiline?area:field)(labels[key]||'Your words',b.text,`data-block="${b.id}" data-prop="text" maxlength="2000"`);}
function renderInspector(){const root=$('#inspector-content');$$('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===activeTab);b.setAttribute('aria-selected',b.dataset.tab===activeTab);});
  if(activeTab==='details'){
    const artwork=project.assets.find(a=>a.id===page().mediaId);const visible=page().blocks.filter(b=>!b.hidden);const hidden=page().blocks.length-visible.length;
    if(page().kind==='blessing'){
      let html='<h2 class="panel-heading">A meaningful beginning.</h2><p class="panel-description">Your blessing uses this page’s design. Edit the words below, or select text on the card to style it.</p>'+blessingControl();
      for(const [key,label] of [['blessingArabic','Arabic blessing'],['blessingTranslation','English translation'],['blessingCustom','Opening words']]){const b=page().blocks.find(b=>b.key===key);if(b)html+=area(label,b.text,`data-block="${b.id}" data-prop="text" maxlength="2000" ${key==='blessingArabic'?'lang="ar" class="arabic-input"':''}`);}
      html+='<p class="hint">Choose another template at any time. Your words stay editable and follow its colors.</p><button class="button outline full" data-action="add-text">+ Add your own text</button>';root.innerHTML=html;return;
    }
    let html='<h2 class="panel-heading">Your story, your words.</h2><p class="panel-description">The little details that make it personal.</p>';
    if(artwork&&artwork.kind!=='frame')html+='<div class="artwork-info"><strong>Your original lettering is preserved.</strong><p>Names, dates and blessings inside this image are part of the artwork. Add extra text below, or start with an editable design to write your own invitation.</p><button class="button outline full" data-action="editable-version">Start an editable version</button></div>';
    if(visible.length)html+=selectField('The occasion',page().occasion,'id="occasion"',OCCASIONS.map(([id,name])=>[id,name]));
    if(hidden)html+=`<div class="hidden-text-note">${hidden} editable text layer${hidden===1?' is':'s are'} hidden. <button class="quiet" data-action="restore-text">Show saved text</button></div>`;
    if(!visible.length&&!artwork)html+='<p class="hint">Add your own text to begin.</p>';
    html+=blessingControl()+'<button class="button outline full" data-action="family-wording">Couple & family details…</button><p class="hint">Add parents, son of / daughter of, hosts, RSVP and compliments. Choose one page or a three-page invitation.</p>';
    if(hasBlessingHeading(page()))for(const [key,label] of [['blessingArabic','Arabic blessing'],['blessingTranslation','English translation'],['blessingCustom','Opening words']]){const b=page().blocks.find(b=>b.key===key);if(b)html+=area(label,b.text,`data-block="${b.id}" data-prop="text" maxlength="2000" ${key==='blessingArabic'?'lang="ar" class="arabic-input"':''}`);}
    if(page().blocks.some(b=>['family1','family2'].includes(b.key)&&!b.hidden))html+=section('THE COUPLE & THEIR FAMILIES')+detailField('name1')+detailField('family1',true)+detailField('name2')+detailField('family2',true)+detailField('overline');
    else if(page().blocks.some(b=>b.key==='name2'&&!b.hidden))html+=section('THE HAPPY COUPLE')+`<div class="form-row">${detailField('name1')}${detailField('name2')}</div>`+detailField('overline');else html+=detailField('name1')+detailField('overline');
    html+=detailField('host',true)+detailField('message',true)+detailField('eventTitle',true)+detailField('schedule',true);
    if(page().blocks.some(b=>b.key==='date'&&!b.hidden))html+='<div class="form-divider"></div>'+section('WHEN & WHERE')+detailField('date')+detailField('time');
    html+=detailField('venue')+detailField('address')+detailField('footer')+detailField('rsvp',true)+detailField('compliments',true)+detailField('recipient',true);
    const custom=page().blocks.filter(b=>b.key==='custom'&&!b.hidden);if(custom.length)html+=section('YOUR EXTRA WORDS')+custom.map(b=>area('Custom text',b.text,`data-block="${b.id}" data-prop="text" maxlength="2000"`)).join('');
    html+='<div class="form-divider"></div><button class="button outline full" data-action="add-text">+ Add your own text</button><button class="quiet full" data-action="add-recipient">♡ Add a guest greeting</button><p class="hint">Tip: select text on the card to change its font, size, color, or position.</p>';root.innerHTML=html;
  }else if(activeTab==='design'){
    const s=selected();let html='<h2 class="panel-heading">Make it feel like you.</h2><p class="panel-description">A little color. A little character.</p>';
    if(s)html+=`<div class="text-layer-box">${section('SELECTED TEXT')} ${area('Your words',s.text,`data-block="${s.id}" data-prop="text" maxlength="2000"`)}${selectField('Typeface',s.font,`data-block="${s.id}" data-prop="font"`,[['serif','Elegant serif'],['sans','Clean & modern'],['script','Handwritten'],['arabic','Arabic · Amiri']])}<div class="form-row">${field('Size',s.size,`data-block="${s.id}" data-prop="size" min="8" max="160"`,'number')}${field('Text color',s.color||((s.key==='name1'||s.key==='name2')?page().accent:page().ink),`data-block="${s.id}" data-prop="color"`,'color')}</div><div class="form-row">${selectField('Style',s.style,`data-block="${s.id}" data-prop="style"`,[['normal','Regular'],['italic','Italic']])}${selectField('Alignment',s.align,`data-block="${s.id}" data-prop="align"`,[['left','Left'],['center','Center'],['right','Right']])}</div><label class="form-field"><span>Text box width · ${Math.round(s.width*100)}%</span><input type="range" data-block="${s.id}" data-prop="width" min="0.15" max="0.95" step="0.01" value="${s.width}"></label><div class="inline-actions"><button class="quiet" data-action="center-text">Center text</button><button class="quiet" data-action="duplicate-text">Duplicate</button><button class="quiet" data-action="delete-text">Delete</button></div></div>`;
    html+=section('YOUR PALETTE')+`<div class="form-row">${field('Paper',page().background,'data-page-prop="background"','color')}${field('Text',page().ink,'data-page-prop="ink"','color')}</div>`+field('Accent & names',page().accent,'data-page-prop="accent"','color');
    html+='<div class="palette-row">'+TEMPLATES.map(t=>`<button class="palette-swatch" data-palette="${t.id}" style="background:${t.background};border-color:${t.accent}" title="${esc(t.name)} colors" aria-label="Use ${esc(t.name)} colors"></button>`).join('')+'</div>';
    if(page().blocks.some(b=>b.hidden))html+='<button class="quiet full" data-action="restore-text">Show saved text layers</button>';
    if(!page().mediaId){html+=`<label class="form-field"><input type="checkbox" data-page-prop="border" ${page().border?'checked':''}> Decorative border</label><label class="form-field"><input type="checkbox" data-page-prop="ornament" ${page().ornament?'checked':''}> Little floral emblem</label>`;if(page().decoration==='royal')html+='<p class="hint">The navy artwork includes its own border. Choose another template for an adjustable border.</p>';}
    else html+=selectField('Background fit',page().mediaFit,'data-page-prop="mediaFit"',[...(project.assets.find(a=>a.id===page().mediaId)?.frameStyle==='ornate'?[['frame','Fit decorative frame']]:[]),['cover','Fill the card'],['contain','Show the whole upload']])+`<label class="form-field"><span>Darken background · ${Math.round(page().overlay*100)}%</span><input type="range" data-page-prop="overlay" min="0" max="0.9" step="0.05" value="${page().overlay}"></label><button class="quiet full" data-action="remove-bg">Remove custom background</button>`;
    html+='<div class="form-divider"></div>'+section('TYPE & LAYOUT')+`<label class="form-field"><span>Typeface for all text</span><select id="global-font"><option value="">Choose a typeface…</option><option value="serif">Elegant serif</option><option value="sans">Clean & modern</option><option value="script">Handwritten</option></select></label><button class="button outline full" data-action="add-text">+ Add text</button>`;
    if(project.mode==='video')html+='<div class="form-divider"></div>'+section('A LITTLE MOVEMENT')+selectField('Animation',page().animation,'data-page-prop="animation"',[['gentle','Soft entrance'],['sparkle','Floating lights'],['none','Keep it still']]);root.innerHTML=html;
  }else if(activeTab==='pages'){
    root.innerHTML=`<h2 class="panel-heading">Every part of the story.</h2><p class="panel-description">A cover, a ceremony, a celebration. Give each moment a page.</p><div class="page-manager">${project.pages.map((p,i)=>`<div class="page-manager-item ${i===pageIndex?'active':''}"><div class="page-manager-title"><button class="quiet" data-action="select-page" data-index="${i}">${i+1}. ${esc(p.name)}</button><span class="hint" data-duration-index="${i}">${p.duration}s</span></div><div class="page-manager-tools"><button class="quiet" data-action="move-page" data-index="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="Move page ${i+1} earlier">↑</button><button class="quiet" data-action="move-page" data-index="${i}" data-direction="1" ${i===project.pages.length-1?'disabled':''} aria-label="Move page ${i+1} later">↓</button><button class="quiet" data-action="duplicate-page" data-index="${i}">Duplicate</button><button class="quiet" data-action="delete-page" data-index="${i}" ${project.pages.length===1?'disabled':''}>Delete</button></div></div>`).join('')}</div><button class="quiet full" data-action="add-page">+ Add another page</button><div class="form-divider"></div>${section('THIS PAGE')}${field('Page name',page().name,'data-page-prop="name" maxlength="80"')}${field('Duration in seconds (video)',page().duration,'data-page-prop="duration" min="2" max="20"','number')}${selectField('Transition to the next page',page().transition,'data-page-prop="transition"',[['fade','Soft crossfade'],['slide','Slide across'],['none','Simple cut']])}<div class="info-box"><span id="page-summary">${project.pages.length} page${project.pages.length>1?'s':''} · ${totalDuration(project)} seconds of celebration.</span><br>Image cards download as one image per page.</div>`;
  }else if(activeTab==='music'){
    const custom=project.assets.find(a=>a.id===project.music.customId);
    root.innerHTML=`<h2 class="panel-heading">Set the mood.</h2><p class="panel-description">A gentle soundtrack for your next chapter.</p><div class="track-list">${TRACKS.map(t=>`<button class="track-button ${project.music.track===t.id?'active':''}" data-track="${t.id}"><span class="track-icon">${t.icon}</span><span><strong>${t.name}</strong><small>${t.description}</small></span></button>`).join('')}${custom?`<button class="track-button ${project.music.track==='custom'?'active':''}" data-track="custom"><span class="track-icon">♫</span><span><strong>${esc(custom.name.slice(0,26))}</strong><small>Your own soundtrack</small></span></button>`:''}</div>${project.music.track!=='none'?`<button class="button outline full" id="sample-music">${musicSample?'■ Stop listening':'▷ Listen for a moment'}</button><label class="form-field" style="margin-top:20px"><span>Keep it light · ${Math.round(project.music.volume*100)}%</span><input id="music-volume" type="range" min="0" max="1" step="0.01" value="${project.music.volume}"></label>`:''}<div class="form-divider"></div><label class="upload-zone"><span>♫</span><strong>Bring your own music</strong><small>MP3, WAV, OGG, M4A · up to 20 MB</small><input type="file" id="music-upload" accept="audio/*" hidden></label><p class="hint">Built-in tracks are original generated instrumentals. Upload music you have permission to use. Music is included in video downloads; uploaded video backgrounds are kept silent.</p>${project.mode==='image'&&project.music.track!=='none'?'<div class="info-box">Switch to Video card to include your soundtrack.</div>':''}`;
  }
}

function selectPage(index){if(busy)return;stopPreview();pageIndex=Math.min(project.pages.length-1,Math.max(0,index));selectedId=null;redraw();}
function switchTab(tab){activeTab=tab;renderInspector();}
function toggleLibrary(tab){libraryTab=tab;$$('[data-library]').forEach(b=>{b.classList.toggle('active',b.dataset.library===tab);b.setAttribute('aria-selected',b.dataset.library===tab);});$('#template-library').hidden=tab!=='templates';$('#uploads-library').hidden=tab!=='uploads';}
function updateTime() {const total=totalDuration(project);$('#time-label').textContent=`${formatTime(previewSeconds)} / ${formatTime(total)}`;$('#timeline').value=total?Math.round(previewSeconds/total*1000):0;}
function formatTime(t){return `${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}`;}
async function stopPreview(){previewPlaying=false;cancelAnimationFrame(previewFrame);previewFrame=null;$('#play-preview').textContent='▶';$('#play-preview').setAttribute('aria-label','Play video preview');const music=previewMusic;previewMusic=null;await music?.stop();assetMedia.forEach(v=>v.pause());}
async function playPreview(){if(busy)return;if(previewPlaying){await stopPreview();return;}await stopSample();try{await readyImages(project);const remaining=totalDuration(project)-previewSeconds;if(remaining<.1)previewSeconds=0;previewMusic=await createMusicSession(project,totalDuration(project)-previewSeconds,{audible:true});for(const p of project.pages){const v=assetMedia.get(p.mediaId);if(v){v.currentTime=previewSeconds%v.duration;await v.play();}}
    previewPlaying=true;const from=previewSeconds,start=performance.now();$('#play-preview').textContent='Ⅱ';$('#play-preview').setAttribute('aria-label','Pause video preview');previewMusic?.start(from);const loop=()=>{if(!previewPlaying)return;previewSeconds=Math.min(totalDuration(project),(performance.now()-start)/1000+from);drawTimeline(canvas,project,previewSeconds,{width:800});fitCanvas();updateTime();if(previewSeconds>=totalDuration(project)){stopPreview();return;}previewFrame=requestAnimationFrame(loop);};loop();
  }catch(e){await stopPreview();toast(e.message);}}
async function stopSample(){clearTimeout(sampleTimer);const sample=musicSample;musicSample=null;await sample?.stop();if($('#sample-music'))$('#sample-music').textContent='▷ Listen for a moment';}

function openModal(html){modal.classList.remove('blessing-dialog');modal.innerHTML=`<div class="modal-inner">${html}</div>`;if(!modal.open)modal.showModal();}
function modalHeader(title){return `<div class="modal-header"><h2>${title}</h2><button class="close-modal" data-close aria-label="Close dialog">×</button></div>`;}
function addPageDialog(){if(project.pages.length>=12){toast('One beautiful story, up to 12 pages.');return;}openModal(modalHeader('Give the moment a page.')+'<p>Choose a starting point. Every word is editable.</p><div class="track-list">'+[['blessing','An opening blessing','Arabic, English, or your own words · matches your design'],['invitation','The invitation','All the lovely essentials'],['cover','A little beginning','Names, a date, a new chapter'],['schedule','The celebrations','Mehndi, sangeet, ceremony & more'],['rsvp','With love & RSVP','Make it easy to say yes'],['blank','A blank canvas','Start with your own ideas']].map(([id,name,desc])=>`<button class="track-button" data-new-page="${id}"><span class="track-icon">✧</span><span><strong>${name}</strong><small>${desc}</small></span></button>`).join('')+'</div>');}
function applyTemplate(id){const t=TEMPLATES.find(t=>t.id===id);if(!t)return;change(()=>{Object.assign(page(),{template:id,background:t.background,ink:t.ink,accent:t.accent,decoration:t.decoration,mediaId:null});setTextVisibility(page(),true);selectedId=null;});}
async function readFile(file,maxMB,type){if(file.size>maxMB*1024*1024)throw new Error(`Please choose a file smaller than ${maxMB} MB.`);if(project.assets.length>=24)throw new Error('This project has 24 uploads. Start a new project to add more.');
  if(type==='background'&&!/^(image\/(png|jpeg|webp|gif)|video\/(mp4|webm|quicktime))$/.test(file.type))throw new Error('Please use a JPG, PNG, WebP, GIF, MP4, MOV or WebM file.');if(type==='music'&&!file.type.startsWith('audio/'))throw new Error('Please choose an audio file.');
  if(project.assets.reduce((n,a)=>n+a.src.length,0)+file.size*1.34>160000000)throw new Error('This project is getting large. Use smaller uploads (120 MB total maximum).');
  const src=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(new Error('The file could not be read.'));r.readAsDataURL(file);});return {id:uid(),name:file.name,type:file.type.split('/')[0],src};
}
async function uploadBackground(file){if(!file||busy)return;try{
  const asset=await readFile(file,80,'background');asset.kind=$('#upload-kind').value;
  const draft=snapshot();draft.assets.push(asset);applyArtwork(draft.pages[pageIndex],asset);await readyImages(draft);
  change(()=>{project=draft;selectedId=null;if(asset.type==='video')project.mode='video';});toggleLibrary('uploads');renderUploaded();toast(asset.kind==='frame'?'Backdrop ready. Your text is editable.':'Artwork ready. Existing lettering stays clear.');
}catch(e){toast(e.message);}}
function renderUploaded(){const root=$('#uploaded-assets');root.innerHTML='';for(const a of project.assets.filter(a=>a.type!=='audio')){const b=document.createElement('button');b.className='uploaded-item';b.dataset.asset=a.id;const media=document.createElement(a.type==='video'?'video':'img');media.src=a.src;if(a.type==='video'){media.muted=true;media.preload='metadata';}media.alt='';const span=document.createElement('span');span.textContent=a.name;const tag=document.createElement('small');tag.textContent=a.kind==='frame'?'Editable backdrop':'Existing lettering';span.append(tag);b.append(media,span);root.append(b);}}
function renderOriginals(){
  $('#original-assets').innerHTML=ORIGINALS.map(a=>`<button data-original="${esc(a.src)}"><img src="${esc(a.src)}" loading="lazy" alt=""><span>${esc(a.name)}</span><small>${a.kind==='frame'?'Empty frame · add your text':a.kind==='blessing'?'Blessing · use as it is':'Finished card · existing text'}</small></button>`).join('');
}
async function useOriginal(src){if(busy)return;try{
  const original=ORIGINALS.find(a=>a.src===src);if(!original)return;
  let a=project.assets.find(a=>a.name===original.name&&a.kind===original.kind);
  if(!a){const response=await fetch(new URL(src,location.href));if(!response.ok)throw new Error('The original asset is unavailable.');const blob=await response.blob();a={...await readFile(new File([blob],original.name,{type:blob.type}),80,'background'),kind:original.kind,frameStyle:original.frameStyle,background:original.background,ink:original.ink};}
  const draft=snapshot();if(!draft.assets.some(asset=>asset.id===a.id))draft.assets.push(a);applyArtwork(draft.pages[pageIndex],a);await readyImages(draft);
  change(()=>{project=draft;selectedId=null;activeTab='details';});renderUploaded();toast(original.kind==='frame'?'Empty frame ready for your wording.':'Original artwork preserved. Extra text is optional.');
}catch(e){toast(e.message);}}

