inspector.addEventListener('click',async e=>{
  const track=e.target.closest('[data-track]');if(track){await stopSample();change(()=>{project.music.track=track.dataset.track;if(track.dataset.track!=='none')project.mode='video';});return;}
  const palette=e.target.closest('[data-palette]');if(palette){const t=TEMPLATES.find(t=>t.id===palette.dataset.palette);change(()=>{Object.assign(page(),{background:t.background,ink:t.ink,accent:t.accent});});return;}
  if(e.target.closest('#sample-music')){if(musicSample){await stopSample();return;}const button=$('#sample-music');button.disabled=true;button.textContent='A moment…';try{await stopPreview();musicSample=await createMusicSession(project,12,{audible:true});musicSample?.start();button.disabled=false;button.textContent='■ Stop listening';sampleTimer=setTimeout(stopSample,12000);}catch(error){button.disabled=false;button.textContent='▷ Listen for a moment';toast(error.message);}return;}
  const b=e.target.closest('[data-action]');if(!b)return;const i=Number(b.dataset.index),action=b.dataset.action;
  if(action==='family-wording')return familyWordingDialog();
  if(action==='blessing')return blessingDialog();
  if(action==='remove-blessing')return change(()=>{const result=setBlessing(project,pageIndex,{placement:'none'});project=result.project;pageIndex=result.index;selectedId=null;});
  if(action==='restore-text')return change(()=>setTextVisibility(page(),true));
  if(action==='editable-version'){const a=project.assets.find(a=>a.id===page().mediaId);applyTemplate(a?.kind==='blessing'?'royal':'gulmohar');toast('Your wording is editable. Undo restores the original artwork.');return;}
  if(action==='add-page')return addPageDialog();if(action==='select-page')return selectPage(i);
  if(action==='move-page'){change(()=>{const dest=i+Number(b.dataset.direction),p=project.pages.splice(i,1)[0];project.pages.splice(dest,0,p);pageIndex=dest;selectedId=null;});return;}
  if(action==='duplicate-page'){if(project.pages.length>=12)return toast('A project can have up to 12 pages.');change(()=>{const p=clone(project.pages[i]);p.id=uid();p.name+=' (copy)';p.blocks.forEach(x=>x.id=uid());project.pages.splice(i+1,0,p);pageIndex=i+1;selectedId=null;});return;}
  if(action==='delete-page'&&project.pages.length>1){change(()=>{project.pages.splice(i,1);pageIndex=Math.min(i,project.pages.length-1);selectedId=null;});return;}
  if(action==='add-text'){if(page().blocks.length>=40)return toast('A page can have up to 40 text blocks.');change(()=>{const b=block('custom','Your beautiful words',.5,28);page().blocks.push(b);selectedId=b.id;activeTab='design';});return;}
  if(action==='add-recipient'){change(()=>{let b=page().blocks.find(b=>b.key==='recipient'&&!b.hidden);if(!b){b=block('recipient','Dear {{name}} {{family}}',hasBlessingHeading(page())?.32:.19,16,'italic');page().blocks.push(b);}selectedId=b.id;activeTab='design';});toast('Use Bulk create to replace guest placeholders.');return;}
  if(action==='remove-bg')return change(()=>{page().mediaId=null;setTextVisibility(page(),true);selectedId=null;});
  if(!selected())return;if(action==='delete-text')change(()=>{page().blocks=page().blocks.filter(b=>b.id!==selectedId);selectedId=null;});
  if(action==='duplicate-text'){if(page().blocks.length>=40)return toast('A page can have up to 40 text blocks.');change(()=>{const b=clone(selected());b.id=uid();b.y=Math.min(.97,b.y+.04);b.key='custom';page().blocks.push(b);selectedId=b.id;});}
  if(action==='center-text')change(()=>{selected().x=.5;selected().align='center';});
});
