let blessingPlacement='heading';
function blessingDialog(placement){
  const existing=relatedBlessing(),words=blessingOptions(existing||newPage(page().template,'blessing'));
  const artwork=project.assets.find(a=>a.id===page().mediaId);
  const canHead=page().kind==='blessing'?project.pages.some(p=>p.kind!=='blessing'):!artwork||artwork.kind==='frame';
  blessingPlacement=placement||(existing?(existing.kind==='blessing'?'opening':'heading'):project.mode==='video'||!canHead?'opening':'heading');
  openModal(modalHeader(existing?'Make the blessing yours.':'Begin with a blessing.')+`<p>Choose Arabic, English, or your own words. The blessing follows your card’s colors and design.</p><div class="blessing-editor"><div class="blessing-settings"><fieldset class="blessing-placement"><legend>Where should it appear?</legend><label><input type="radio" name="blessing-placement" value="heading" ${blessingPlacement==='heading'?'checked':''} ${!canHead?'disabled':''}><span><strong>Above the invitation</strong><small>Make room at the top of this card.</small></span></label><label><input type="radio" name="blessing-placement" value="opening" ${blessingPlacement==='opening'?'checked':''}><span><strong>A separate opening page</strong><small>Begin with a page just for the blessing.</small></span></label></fieldset>${!canHead?'<p class="hint">A separate opening keeps existing artwork clear.</p>':''}${selectField('Opening words',words.preset,'id="blessing-preset"',BLESSING_PRESETS)}<div id="blessing-arabic-field">${area('Arabic blessing',words.arabic,'id="blessing-arabic" lang="ar" class="arabic-input" maxlength="2000"')}</div><div id="blessing-translation-field">${area('English translation',words.translation,'id="blessing-translation" maxlength="2000"')}</div><div id="blessing-custom-field">${area('Your opening words',words.text,'id="blessing-custom" maxlength="2000"')}</div><p class="hint">Every line stays editable. You can change the font, size and position on the card.</p></div><figure class="blessing-preview"><canvas id="blessing-preview" aria-label="Live preview of your blessing"></canvas><figcaption id="blessing-preview-label"></figcaption></figure></div><div id="blessing-error" class="guest-error" role="alert"></div><div class="modal-bottom"><p class="hint">Preview updates as you type.</p><button class="button" id="apply-blessing">${existing?'Save blessing':'Add blessing'} →</button></div>`);
  modal.classList.add('blessing-dialog');renderBlessingPreview();
}
function readBlessingOptions(){return {placement:blessingPlacement,preset:$('#blessing-preset').value,arabic:$('#blessing-arabic').value.trim(),translation:$('#blessing-translation').value.trim(),text:$('#blessing-custom').value.trim()};}
function renderBlessingPreview(){
  const options=readBlessingOptions();
  $('#blessing-arabic-field').hidden=!['bilingual','arabic'].includes(options.preset);$('#blessing-translation-field').hidden=!['bilingual','english'].includes(options.preset);$('#blessing-custom-field').hidden=options.preset!=='custom';
  try{
    if((['bilingual','arabic'].includes(options.preset)&&!options.arabic)||(['bilingual','english'].includes(options.preset)&&!options.translation)||(options.preset==='custom'&&!options.text))throw new Error('Add your opening words, or choose a different wording option.');
    const result=setBlessing(snapshot(),pageIndex,options),p=result.project.pages[result.index];drawPage($('#blessing-preview'),{...result.project,mode:'image'},p,{width:500,time:1.2});
    $('#blessing-preview-label').textContent=`${blessingPlacement==='heading'?'Your invitation, with a blessing':'Your opening page'} · ${TEMPLATES.find(t=>t.id===p.template)?.name||'Your design'}`;
    $('#blessing-error').textContent='';$('#apply-blessing').disabled=false;
  }catch(error){$('#blessing-error').textContent=error.message;$('#apply-blessing').disabled=true;}
}
modal.addEventListener('close',()=>modal.classList.remove('blessing-dialog'));
modal.addEventListener('change',e=>{if(e.target.name==='blessing-placement'){blessingPlacement=e.target.value;renderBlessingPreview();}if(e.target.id==='blessing-preset')renderBlessingPreview();});
modal.addEventListener('input',e=>{if(['blessing-arabic','blessing-translation','blessing-custom'].includes(e.target.id))renderBlessingPreview();});
modal.addEventListener('click',async e=>{
  if(!e.target.closest('#apply-blessing')||busy)return;
  const button=$('#apply-blessing');button.disabled=true;
  try{const result=setBlessing(snapshot(),pageIndex,readBlessingOptions());await readyImages(result.project);change(()=>{project=result.project;pageIndex=result.index;selectedId=null;activeTab='details';});modal.close();toast('Your blessing is ready. Every word is editable.');}
  catch(error){$('#blessing-error').textContent=error.message;button.disabled=false;}
});

const familyFields=[['recipient','Guest greeting'],['host','Hosts / parents inviting'],['message','Invitation request'],['eventTitle','Ceremony or reception'],['name1','First person’s name'],['family1','Son of / first person’s family'],['name2','Second person’s name'],['family2','Daughter of / second person’s family'],['date','Date'],['time','Time / lunch / dinner'],['venue','Venue'],['address','Address'],['rsvp','RSVP names & contact'],['compliments','With best compliments from']];
function familyWordingDialog(){
  const value=key=>[page(),...project.pages.filter(p=>p!==page())].flatMap(p=>p.blocks).find(b=>b.key===key&&!b.hidden)?.text;
  const defaults={recipient:'To,\n{{name}} {{family}}',host:'Mr. & Mrs. Sharma',message:'request the honour of your presence at the',eventTitle:occasionTitle(page().occasion),name1:'Aarav',family1:'Son of Mr. & Mrs. Sharma',name2:'Meera',family2:'Daughter of Mr. & Mrs. Kapoor',date:'SUNDAY, 14 FEBRUARY 2027',time:'4:00 PM ONWARDS',venue:'The Leela Palace',address:'JAIPUR, RAJASTHAN',rsvp:'RSVP: The Sharma family\n+91 90000 00000',compliments:'With best compliments from,\nFamily & friends'};
  const existing=relatedBlessing();
  const fields=familyFields.map(([key,label])=>area(label,value(key)??defaults[key],`id="wording-${key}" maxlength="2000"`));
  openModal(modalHeader('Your families. Your invitation.')+'<p>Add the people and details that matter. Leave optional lines empty. All wording, including son of, daughter of and parent names, stays editable.</p>'+selectField('Invitation layout','single','id="family-layout"',[['single','One page · all invitation details'],['sequence','Three pages · families, couple, event']])+selectField('Opening blessing',existing?blessingOptions(existing).preset:'none','id="family-blessing"',[['none','No opening blessing'],...BLESSING_PRESETS])+ '<p class="hint">Adds an editable opening page in your chosen design. Use Edit blessing to customize its words.</p>'+[['Guests & hosts',fields.slice(0,4)],['The couple & their families',fields.slice(4,8)],['Date, venue & replies',fields.slice(8)]].map(([title,items])=>`<details class="wording-group" open><summary>${title}</summary>${items.join('')}</details>`).join('')+'<p class="hint">For bulk invitations, {{name}} and {{family}} become each guest’s details. For one card, type a guest name or leave the greeting empty.</p><div class="info-box">One page updates this invitation page. Three pages replaces the invitation sequence. You can undo either choice.</div><div class="modal-bottom"><button class="button" id="apply-family-wording">Use these details →</button></div><div id="wording-error" role="alert" class="hint"></div>');
}
modal.addEventListener('click',async e=>{
  if(!e.target.closest('#apply-family-wording')||busy)return;
  const button=$('#apply-family-wording');button.disabled=true;
  try{
    const words=Object.fromEntries(familyFields.map(([key])=>[key,$(`#wording-${key}`).value.trim()]));words.ampersand='&';
    const sequence=$('#family-layout').value==='sequence',preset=$('#family-blessing').value,includeBlessing=preset!=='none';
    const existing=relatedBlessing(),base=matchingDesign(project,page());
    const pages=familyInvitationPages(base,words,{sequence});const occasion=OCCASIONS.find(o=>o[0]!=='custom'&&words.eventTitle.toLowerCase().includes(o[0]))?.[0]||'custom';pages.forEach(p=>p.occasion=occasion);const draft=snapshot();
    if(includeBlessing){
      pages.unshift(newBlessingPage(base,{...(existing?blessingOptions(existing):{}),preset}));
    }
    let start=pageIndex;
    if(sequence){draft.pages=pages;start=0;}else{if(existing?.kind==='blessing'&&existing!==page()){start--;draft.pages.splice(start,2,...pages);}else draft.pages.splice(start,1,...pages);}
    if(draft.pages.length>12)throw new Error('An invitation can have up to 12 pages. Remove a page first or choose no opening blessing.');
    await readyImages(draft);change(()=>{project=draft;pageIndex=start+Number(includeBlessing);selectedId=null;activeTab='details';});modal.close();renderUploaded();toast(sequence?'Your three-page invitation is ready. Choose a page below to edit it.':'Your family details are ready. Every line can be edited.');
  }catch(error){$('#wording-error').textContent=error.message;button.disabled=false;}
});

let exportFormat='png',exportWidth=1080,exportScope='all',exportAbort=null,bulkGuests=[],bulkRecipient=true,bulkInputMode='list',bulkListText='',bulkFamily='',bulkGreeting='To,\n{{name}} {{family}}',bulkPreviewIndex=0,bulkPreviewPage=0,bulkFileText='',bulkFileCSV=false;
function downloadDialog(){stopPreview();stopSample();exportFormat=project.mode==='video'?'video':'png';exportWidth=1080;exportScope='all';renderDownloadDialog();}
function renderDownloadDialog(){const type=supportedVideoType(),video=exportFormat==='video';openModal(modalHeader('Ready to spread a little joy?')+`<p>Something beautiful, made by you. No watermark, ever.</p><div class="export-choice"><button data-format="png" class="${exportFormat==='png'?'active':''}">▧ PNG<br><small class="hint">Crisp & lovely</small></button><button data-format="jpeg" class="${exportFormat==='jpeg'?'active':''}">▧ JPG<br><small class="hint">Easy to share</small></button><button data-format="video" class="${video?'active':''}">▷ Video<br><small class="hint">${type?.includes('mp4')?'MP4':'WebM'}</small></button></div>${selectField('Resolution',String(exportWidth),'id="export-resolution"',(video?['720','1080']:['720','1080','1440','2160']).map(w=>[w,`${w} × ${dimensions(project.aspect,Number(w)).height} px${w==='1080'?' · recommended':''}`]))}${!video&&project.pages.length>1?selectField('Pages',exportScope,'id="export-scope"',[['all',`All ${project.pages.length} pages · ZIP`],['current','Only the current page']]):''}<div class="info-box">${video?`${totalDuration(project)} seconds · 30 fps · ${project.music.track==='none'?'silent video':'music included'}<br>Video renders in real time. Keep this tab visible.${!type?'<br>Video recording is unavailable in this browser.':''}`:'High quality images, ready for sharing or printing.'}${project.pages.some(p=>p.blocks.some(b=>/\{\{\s*(name|family|event)\s*\}\}/i.test(b.text)))?'<br>Your card has guest placeholders. Use Bulk create to fill them with real names.':''}</div><div class="modal-bottom"><p class="hint">Your files are created on your device. Your invitation stays private.</p><button class="button" id="start-export" ${video&&!type?'disabled':''}>Download ${video?'video':exportScope==='all'&&project.pages.length>1?'pages':'card'} ↓</button></div><div id="export-progress" hidden></div>`);}
$('#export-button').addEventListener('click',downloadDialog);
modal.addEventListener('change',e=>{if(e.target.id==='export-resolution')exportWidth=Number(e.target.value);if(e.target.id==='export-scope'){exportScope=e.target.value;renderDownloadDialog();}if(e.target.id==='bulk-add-recipient')bulkRecipient=e.target.checked;if(e.target.id==='bulk-guest-select')renderBulkPreview(Number(e.target.value));if(e.target.id==='bulk-resolution')exportWidth=Number(e.target.value);if(e.target.id==='bulk-format'){exportFormat=e.target.value;if(exportFormat==='video'&&exportWidth>1080)exportWidth=1080;renderBulkDialog();}});
modal.addEventListener('click',async e=>{const b=e.target.closest('[data-format]');if(b&&!busy){exportFormat=b.dataset.format;if(exportFormat==='video'&&exportWidth>1080)exportWidth=1080;renderDownloadDialog();}if(e.target.closest('#start-export'))await runExport(false);if(e.target.closest('#cancel-export'))exportAbort?.abort();});
function setProgress(fraction,message){const box=$('#export-progress');if(!box)return;box.hidden=false;box.className='progress-box';box.innerHTML=`<span>${esc(message)}</span><progress max="1" value="${fraction}"></progress>`;}
function setBusy(value){busy=value;$$('dialog button,dialog select,dialog input,dialog textarea').forEach(b=>b.disabled=value);$('.close-modal')?.toggleAttribute('disabled',value);$('#export-button').disabled=value;$('#bulk-button').disabled=value;$('#save-project').disabled=value;updateHistory();if(value){const cancel=document.createElement('button');cancel.className='quiet full';cancel.id='cancel-export';cancel.textContent='Cancel export';$('.modal-inner').append(cancel);}else{$('#cancel-export')?.remove();if($('#bulk-results')){updateBulkResults();$('#bulk-add-recipient').disabled=!bulkGreetingPage(project)||hasGuestName(project);}}}
async function runExport(bulk){if(busy)return;const effective=bulk?bulkProject():snapshot();const guests=bulk?bulkGuests:[null];if(!guests.length)return toast('Add your guest list first.');if(bulk&&!hasGuestName(effective))return toast('Add {{name}} to an editable text layer, or enable a guest greeting.');await stopPreview();await stopSample();setBusy(true);exportAbort=new AbortController();const files=[];const format=exportFormat;effective.mode=format==='video'?'video':'image';try{
  for(let i=0;i<guests.length;i++){if(exportAbort.signal.aborted)throw new DOMException('Export cancelled','AbortError');const guest=guests[i],prefix=bulk?`${String(i+1).padStart(3,'0')}-${safeFilename(guest.name)}/`:'';const total=guests.length;
    if(format==='video'){const result=await exportVideo(effective,{width:exportWidth,guest,signal:exportAbort.signal,onProgress:(f,msg)=>setProgress((i+f)/total,`${bulk?`Guest ${i+1} of ${total} · `:''}${msg}`)});files.push({name:`${prefix}${safeFilename(effective.name)}.${result.extension}`,blob:result.blob});}
    else{const images=await exportImages(effective,{width:exportWidth,format,guest,pages:!bulk&&exportScope==='current'?[effective.pages[pageIndex]]:effective.pages});for(const img of images)files.push({name:prefix+img.name,blob:img.blob});setProgress((i+1)/total,bulk?`Made with love for ${guest.name} · ${i+1} of ${total}`:'Your card is ready.');await new Promise(res=>setTimeout(res,0));}
    if(files.reduce((n,f)=>n+f.blob.size,0)>500*1024*1024)throw new Error('This batch exceeds 500 MB. Try fewer guests or a lower resolution.');
  }
  if(exportAbort.signal.aborted)throw new DOMException('Export cancelled','AbortError');setProgress(1,files.length>1?'Wrapping up your cards…':'Your invitation is ready.');
  if(files.length===1&&!bulk){const ext=files[0].name.split('.').pop();download(files[0].blob,`${safeFilename(project.name)}.${ext}`);}else download(await makeZip(files),`${safeFilename(project.name)}${bulk?'-personalized':''}.zip`);
  setProgress(1,bulk?`All ${guests.length} personalized invitations are ready. Your ZIP download has started.`:'Made by you, ready to share. Your download has started.');toast('A little joy, ready to share.');
  }catch(error){setProgress(0,error.name==='AbortError'?'Export cancelled. Your project is safe.':error.message);}
  finally{setBusy(false);exportAbort=null;redraw({panel:false});}
}
function bulkProject(){return prepareBulkProject(snapshot(),{addGreeting:bulkRecipient,greeting:bulkGreeting});}
function bulkDialog(){
  stopPreview();stopSample();bulkRecipient=!!bulkGreetingPage(project)&&bulkRecipient;bulkPreviewIndex=0;
  bulkPreviewPage=Math.max(0,bulkProject().pages.findIndex(p=>p.blocks.some(b=>!b.hidden&&/\{\{\s*name\s*\}\}/i.test(b.text))));
  exportFormat=project.mode==='video'?'video':'png';exportWidth=720;renderBulkDialog();
}
function renderBulkDialog(){
  openModal(modalHeader('A personal invitation. For everyone.')+`<p>Set up your invitation once. Add your guest names. Get a complete personalized invitation for each person.</p><div class="bulk-steps"><span>01 · Add your guests</span><span>02 · Preview</span><span>03 · Download a ZIP</span></div><div class="export-choice guest-input-choice"><button data-guest-mode="list" class="${bulkInputMode==='list'?'active':''}">Type or paste names</button><button data-guest-mode="file" class="${bulkInputMode==='file'?'active':''}">Upload a list</button></div>${bulkInputMode==='list'?`<label class="form-field"><span>Guest names · one invitation per line</span><textarea id="guest-list" rows="6" maxlength="160000" placeholder="Ahmed Khan\nPriya Sharma\nMeera &amp; Rohan">${esc(bulkListText)}</textarea></label><p class="hint">Paste names from a message or type them here. Keep a couple or family on one line if they should receive one invitation.</p>`:'<label class="upload-zone"><span>▤</span><strong>Choose a text file or CSV</strong><small>Plain .txt · one name per line. CSV is optional.<br>Up to 200 invitations · file smaller than 1 MB</small><input type="file" id="guest-upload" accept=".txt,.csv,text/plain,text/csv" hidden></label><button class="quiet full" id="sample-list">Download a simple text list ↓</button><button class="quiet full" id="sample-csv">Download a sample CSV ↓</button>'}${field('Family wording for the whole list (optional)',bulkFamily,'id="bulk-family" maxlength="250" placeholder="e.g. & family"')}<p class="hint">For individual family wording or events, use <strong>Name | &amp; family | Walima</strong> on a line, or the optional CSV columns name, family, event.</p><div id="guest-error" class="guest-error" role="alert"></div>${project.pages.some(p=>project.assets.find(a=>a.id===p.mediaId&&a.kind!=='frame'))?'<div class="artwork-info">Lettering inside an image stays the same. Guest names are added only to editable text. The opening blessing stays as it is.</div>':''}<label class="form-field" style="margin-top:15px"><input type="checkbox" id="bulk-add-recipient" ${bulkRecipient?'checked':''} ${!bulkGreetingPage(project)||hasGuestName(project)?'disabled':''}> ${hasGuestName(project)?'Your template already has a guest greeting':'Add a guest greeting to an editable page'}</label>${!bulkGreetingPage(project)?'<p class="hint">To personalize finished artwork, add and position a text layer containing {{name}} in the editor first.</p>':''}<div id="bulk-greeting-field" ${!bulkRecipient||hasGuestName(project)?'hidden':''}>${area('Greeting wording',bulkGreeting,'id="bulk-greeting" maxlength="2000"')}</div><p class="hint">Use <strong>{{name}}</strong>, <strong>{{family}}</strong>, and <strong>{{event}}</strong> anywhere in the card. A name placeholder already on your template takes priority over the automatic greeting.</p>${selectField('File format',exportFormat,'id="bulk-format"',[['png','PNG images'],['jpeg','JPG images'],['video',`Video · ${supportedVideoType()?.includes('mp4')?'MP4':'WebM'}`]])}${selectField('Resolution',String(exportWidth),'id="bulk-resolution"',(exportFormat==='video'?['720','1080']:['720','1080','1440','2160']).map(w=>[w,`${w} × ${dimensions(project.aspect,Number(w)).height} px`]))}<div id="bulk-results"></div><div class="modal-bottom"><p class="hint" id="bulk-summary"></p><button class="button" id="start-bulk" disabled>Create invitations ↓</button></div><div id="export-progress" hidden></div>`);
  updateBulkResults();
}
function updateBulkResults(error=''){
  $('#guest-error').textContent=error;
  $('#bulk-results').innerHTML=bulkGuests.length?`<p class="bulk-count">${bulkGuests.length} guest${bulkGuests.length===1?'':'s'} · ${bulkGuests.length} complete invitation${bulkGuests.length===1?'':'s'}</p><div class="guest-scroll"><table class="bulk-table"><thead><tr><th>Guest</th><th>Family</th><th>Event</th></tr></thead><tbody>${bulkGuests.slice(0,8).map(g=>`<tr><td>${esc(g.name)}</td><td>${esc(g.family)}</td><td>${esc(g.event)}</td></tr>`).join('')}</tbody></table></div>${bulkGuests.length>8?`<p class="hint">Showing 8 of ${bulkGuests.length} guests. All are included in the download.</p>`:''}${selectField('Preview a guest',String(Math.min(bulkPreviewIndex,bulkGuests.length-1)),'id="bulk-guest-select"',bulkGuests.map((g,i)=>[String(i),`${i+1}. ${esc(g.name)}`]))}${project.pages.length>1?selectField('Preview page',String(bulkPreviewPage),'id="bulk-page-select"',project.pages.map((p,i)=>[String(i),`${i+1}. ${esc(p.name)}`])):''}<div class="bulk-preview-wrap"><canvas id="bulk-preview" aria-label="Personalized guest card preview"></canvas></div>`:'';
  const personalized=hasGuestName(bulkProject());
  if(bulkGuests.length&&!personalized&&!error)$('#guest-error').textContent='Include {{name}} in your greeting or an editable card text layer so each invitation is personalized.';
  $('#start-bulk').disabled=!!error||!bulkGuests.length||!personalized||(exportFormat==='video'&&!supportedVideoType());
  $('#start-bulk').textContent=`Create ${bulkGuests.length||''} invitation${bulkGuests.length===1?'':'s'} ↓`;
  $('#bulk-summary').textContent=exportFormat==='video'?`${bulkGuests.length*totalDuration(project)} seconds of rendering. Each guest receives the whole video.`:`One folder per guest, with ${project.pages.length===1?'the invitation page':`all ${project.pages.length} pages`}. Your template stays the same; guest details change.`;
  renderBulkPreview(Math.min(bulkPreviewIndex,bulkGuests.length-1));
}
function readTypedGuests(){try{bulkGuests=bulkListText.trim()?parseGuestList(bulkListText,bulkFamily):[];updateBulkResults();}catch(error){bulkGuests=[];updateBulkResults(error.message);}}
function renderBulkPreview(index){bulkPreviewIndex=Math.max(0,index);const c=$('#bulk-preview');if(c&&bulkGuests[bulkPreviewIndex]){const p=bulkProject();drawPage(c,p,p.pages[bulkPreviewPage]||p.pages[0],{width:400,time:1.2,guest:bulkGuests[bulkPreviewIndex]});}}
$('#bulk-button').addEventListener('click',bulkDialog);
modal.addEventListener('input',e=>{
  if(e.target.id==='guest-list'){bulkListText=e.target.value;readTypedGuests();}
  if(e.target.id==='bulk-family'){bulkFamily=e.target.value;if(bulkInputMode==='list')readTypedGuests();else if(bulkFileText){try{bulkGuests=bulkFileCSV?parseCSV(bulkFileText).map(g=>({...g,family:g.family||bulkFamily})):parseGuestList(bulkFileText,bulkFamily);updateBulkResults();}catch(error){bulkGuests=[];updateBulkResults(error.message);}}}
  if(e.target.id==='bulk-greeting'){bulkGreeting=e.target.value;updateBulkResults();}
});
modal.addEventListener('change',async e=>{
  if(e.target.id==='guest-upload'&&e.target.files[0]){
    try{const file=e.target.files[0];if(file.size>1024*1024)throw new Error('Please use a list smaller than 1 MB.');bulkFileText=await file.text();bulkFileCSV=/\.csv$/i.test(file.name);bulkGuests=bulkFileCSV?parseCSV(bulkFileText).map(g=>({...g,family:g.family||bulkFamily})):parseGuestList(bulkFileText,bulkFamily);bulkPreviewIndex=0;updateBulkResults();}
    catch(error){bulkGuests=[];updateBulkResults(error.message);}
    e.target.value='';
  }
  if(e.target.id==='bulk-add-recipient'){$('#bulk-greeting-field').hidden=!bulkRecipient;updateBulkResults();}
  if(e.target.id==='bulk-page-select'){bulkPreviewPage=Number(e.target.value);renderBulkPreview(bulkPreviewIndex);}
});
modal.addEventListener('click',async e=>{
  const mode=e.target.closest('[data-guest-mode]');if(mode&&!busy){bulkInputMode=mode.dataset.guestMode;bulkGuests=[];bulkFileText='';if(bulkInputMode==='list'&&bulkListText.trim()){try{bulkGuests=parseGuestList(bulkListText,bulkFamily);}catch{}}renderBulkDialog();}
  if(e.target.closest('#sample-list'))download(new Blob(['Ahmed Khan\nPriya Sharma\nMeera & Rohan\n'],{type:'text/plain;charset=utf-8'}),'mehfil-guests.txt');
  if(e.target.closest('#sample-csv'))download(new Blob(['name,family,event\r\nPriya Sharma,& family,Wedding ceremony\r\nAhmed Khan,,Walima reception\r\n"Meera & Rohan",,Sangeet\r\n'],{type:'text/csv;charset=utf-8'}),'mehfil-guests.csv');
  if(e.target.closest('#start-bulk'))await runExport(true);
});

async function init(){try{await initDB();await Promise.all(['16px \"Cormorant Garamond\"','italic 16px \"Cormorant Garamond\"','16px \"DM Sans\"','42px \"Amiri\"'].map(font=>document.fonts.load(font)));await document.fonts.ready;await Promise.all(TEMPLATES.filter(t=>t.asset).map(t=>loadImage(t.asset)));await readyImages(project);renderOriginals();renderUploaded();redraw({templates:true});}catch(error){renderOriginals();renderUploaded();redraw({templates:true});toast(`Some media could not load: ${error.message}`);}}
init();
